mapper.select:
SELECT cs.uuid AS uuid FROM code_sessions cs
JOIN sessions s ON s.uuid = cs.session_uuid AND s.organization_uuid = cs.organization_uuid AND s.workspace_uuid = cs.workspace_uuid
WHERE cs.organization_uuid = #{scope.OrganizationUUID} AND cs.workspace_uuid = #{scope.WorkspaceUUID}
AND cs.external_id = #{scope.CodeSessionID} AND cs.current_worker_epoch = #{scope.WorkerEpoch}
AND cs.status = 'active' AND cs.deleted_at IS NULL AND s.deleted_at IS NULL AND s.status <> 'terminated'
FOR SHARE OF cs

SELECT  FROM sandbox_tool_calls
WHERE  AND code_session_uuid = (SELECT uuid FROM code_sessions WHERE external_id = #{scope.CodeSessionID} AND organization_uuid = #{scope.OrganizationUUID} AND workspace_uuid = #{scope.WorkspaceUUID})
AND thread_id = #{scope.ThreadID} AND external_id = #{scope.CallID}

SELECT  FROM sandbox_tool_calls
WHERE state = 'finalizing' AND finalize_until <= #{now}
ORDER BY finalize_until, id
LIMIT #{limit}
FOR UPDATE SKIP LOCKED
